-- StockFlow MySQL schema (generated by scripts/generate_sql.py)
CREATE DATABASE IF NOT EXISTS stockflow CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE stockflow;

CREATE TABLE categories (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	name VARCHAR(100) NOT NULL, 
	description TEXT, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id)
);
CREATE UNIQUE INDEX ix_categories_name ON categories (name);

CREATE TABLE suppliers (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	name VARCHAR(120) NOT NULL, 
	email VARCHAR(120), 
	phone VARCHAR(30), 
	address VARCHAR(255), 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id)
);
CREATE UNIQUE INDEX ix_suppliers_name ON suppliers (name);

CREATE TABLE users (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	username VARCHAR(50) NOT NULL, 
	email VARCHAR(120) NOT NULL, 
	hashed_password VARCHAR(255) NOT NULL, 
	`role` ENUM('admin','manager','staff') NOT NULL, 
	is_active BOOL NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id)
);
CREATE UNIQUE INDEX ix_users_email ON users (email);
CREATE UNIQUE INDEX ix_users_username ON users (username);

CREATE TABLE orders (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	customer_name VARCHAR(120) NOT NULL, 
	status ENUM('CONFIRMED','COMPLETED','CANCELLED') NOT NULL, 
	total_amount NUMERIC(12, 2) NOT NULL, 
	created_by INTEGER NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(created_by) REFERENCES users (id) ON DELETE RESTRICT
);
CREATE INDEX ix_orders_created_at ON orders (created_at);
CREATE INDEX ix_orders_created_by ON orders (created_by);
CREATE INDEX ix_orders_customer_name ON orders (customer_name);
CREATE INDEX ix_orders_status ON orders (status);

CREATE TABLE products (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	sku VARCHAR(40) NOT NULL, 
	name VARCHAR(150) NOT NULL, 
	description TEXT, 
	price NUMERIC(10, 2) NOT NULL, 
	quantity INTEGER NOT NULL, 
	reorder_level INTEGER NOT NULL, 
	image_path VARCHAR(255), 
	category_id INTEGER NOT NULL, 
	supplier_id INTEGER, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_products_quantity_nonneg CHECK (quantity >= 0), 
	CONSTRAINT ck_products_price_positive CHECK (price > 0), 
	FOREIGN KEY(category_id) REFERENCES categories (id) ON DELETE RESTRICT, 
	FOREIGN KEY(supplier_id) REFERENCES suppliers (id) ON DELETE RESTRICT
);
CREATE INDEX ix_products_category_id ON products (category_id);
CREATE INDEX ix_products_name ON products (name);
CREATE UNIQUE INDEX ix_products_sku ON products (sku);
CREATE INDEX ix_products_supplier_id ON products (supplier_id);

CREATE TABLE order_items (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	order_id INTEGER NOT NULL, 
	product_id INTEGER NOT NULL, 
	quantity INTEGER NOT NULL, 
	unit_price NUMERIC(10, 2) NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_order_items_quantity_positive CHECK (quantity > 0), 
	FOREIGN KEY(order_id) REFERENCES orders (id) ON DELETE CASCADE, 
	FOREIGN KEY(product_id) REFERENCES products (id) ON DELETE RESTRICT
);
CREATE INDEX ix_order_items_order_id ON order_items (order_id);
CREATE INDEX ix_order_items_product_id ON order_items (product_id);

CREATE TABLE stock_movements (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	product_id INTEGER NOT NULL, 
	movement_type ENUM('IN','OUT','SALE','RETURN') NOT NULL, 
	quantity INTEGER NOT NULL, 
	balance_after INTEGER NOT NULL, 
	reference VARCHAR(100), 
	note VARCHAR(255), 
	order_id INTEGER, 
	created_by INTEGER NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(product_id) REFERENCES products (id) ON DELETE RESTRICT, 
	FOREIGN KEY(order_id) REFERENCES orders (id) ON DELETE SET NULL, 
	FOREIGN KEY(created_by) REFERENCES users (id) ON DELETE RESTRICT
);
CREATE INDEX ix_stock_movements_created_at ON stock_movements (created_at);
CREATE INDEX ix_stock_movements_movement_type ON stock_movements (movement_type);
CREATE INDEX ix_stock_movements_product_id ON stock_movements (product_id);
